      SUBROUTINE DFOCUSCC     DERIVATIVE OF FIRST-ORDER TRANSFER MATRIX FOR A QUADRUPOLE C     WITH RESPECT TO MAGNETIC FIELD OR GRADIENTC                    C     LIST OF COMMON BLOCKSC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'C-------------------------------------------------------C      J = JQUAD      CS = R(J,J)      SN = R(J,J+1)      RV(J,J) =  - L*SN*KVK      RV(J+1,J+1)  =  RV(J,J)      IF (KQ2 .NE. 0.0) THEN        RV(J,J+1) = (- SN + L*CS)*KVK/KQ2      ELSE        RV(J,J+1) = 0.0      ENDIF      RV(J+1,J)  =  - (SN + L*CS)*KVK      RETURN      END